1	//! File metadata - the root structure in the Parquet footer
2	
3	const std = @import("std");
4	const safe = @import("../safe.zig");
5	const thrift = @import("../thrift/mod.zig");
6	const schema_mod = @import("schema.zig");
7	const row_group_mod = @import("row_group.zig");
8	
9	pub const SchemaElement = schema_mod.SchemaElement;
10	pub const RowGroup = row_group_mod.RowGroup;
11	pub const KeyValue = row_group_mod.KeyValue;
12	
13	/// File metadata - the root structure in the footer
14	pub const FileMetaData = struct {
15	    version: i32 = 0,
16	    schema: []SchemaElement = &.{},
17	    num_rows: i64 = 0,
18	    row_groups: []RowGroup = &.{},
19	    key_value_metadata: ?[]KeyValue = null,
20	    created_by: ?[]const u8 = null,
21	
22	    const Self = @This();
23	
24	    pub fn parse(allocator: std.mem.Allocator, reader: *thrift.CompactReader) !Self {
25	        var meta = Self{};
26	        reader.resetFieldTracking();
27	
28	        while (try reader.readFieldHeader()) |field| {
29	            switch (field.field_id) {
30	                1 => meta.version = try reader.readI32(),
31	                2 => {
32	                    const list_header = try reader.readListHeader();
33	                    try reader.checkListFits(list_header.size);
34	                    var schema_list = try allocator.alloc(SchemaElement, list_header.size);
35	                    for (0..list_header.size) |i| {
36	                        schema_list[i] = try SchemaElement.parse(allocator, reader);
37	                    }
38	                    meta.schema = schema_list;
39	                },
40	                3 => meta.num_rows = try reader.readI64(),
41	                4 => {
42	                    const list_header = try reader.readListHeader();
43	                    try reader.checkListFits(list_header.size);
44	                    var row_groups_list = try allocator.alloc(RowGroup, list_header.size);
45	                    for (0..list_header.size) |i| {
46	                        row_groups_list[i] = try RowGroup.parse(allocator, reader);
47	                    }
48	                    meta.row_groups = row_groups_list;
49	                },
50	                5 => {
51	                    const list_header = try reader.readListHeader();
52	                    try reader.checkListFits(list_header.size);
53	                    var kvs = try allocator.alloc(KeyValue, list_header.size);
54	                    for (0..list_header.size) |i| {
55	                        kvs[i] = try KeyValue.parse(allocator, reader);
56	                    }
57	                    meta.key_value_metadata = kvs;
58	                },
59	                6 => meta.created_by = try allocator.dupe(u8, try reader.readString()),
60	                else => try reader.skip(field.field_type),
61	            }
62	        }
63	
64	        return meta;
65	    }
66	
67	    /// Serialize to Thrift Compact Protocol
68	    pub fn serialize(self: *const Self, writer: *thrift.CompactWriter) !void {
69	        writer.resetFieldTracking();
70	
71	        try writer.writeFieldHeader(1, .i32);
72	        try writer.writeI32(self.version);
73	
74	        try writer.writeFieldHeader(2, .list);
75	        try writer.writeListHeader(.struct_, safe.castTo(u32, self.schema.len) catch return error.IntegerOverflow);
76	        for (self.schema) |*elem| {
77	            try elem.serialize(writer);
78	        }
79	
80	        try writer.writeFieldHeader(3, .i64);
81	        try writer.writeI64(self.num_rows);
82	
83	        try writer.writeFieldHeader(4, .list);
84	        try writer.writeListHeader(.struct_, safe.castTo(u32, self.row_groups.len) catch return error.IntegerOverflow);
85	        for (self.row_groups) |*rg| {
86	            try rg.serialize(writer);
87	        }
88	
89	        if (self.key_value_metadata) |kvs| {
90	            try writer.writeFieldHeader(5, .list);
91	            try writer.writeListHeader(.struct_, safe.castTo(u32, kvs.len) catch return error.IntegerOverflow);
92	            for (kvs) |*kv| {
93	                try kv.serialize(writer);
94	            }
95	        }
96	
97	        if (self.created_by) |cb| {
98	            try writer.writeFieldHeader(6, .binary);
99	            try writer.writeString(cb);
100	        }
101	
102	        try writer.writeStructEnd();
103	    }
104	};
105

1	//! Recursive flattening and assembly for nested Parquet data
2	//!
3	//! This module provides generalized functions to:
4	//! - Flatten nested `Value` structures into flat column arrays with def/rep levels
5	//! - Assemble flat column data back into nested `Value` structures
6	//!
7	//! These functions handle arbitrary nesting depth (list<struct<list<...>>>).
8	
9	const std = @import("std");
10	const schema_mod = @import("schema.zig");
11	const value_mod = @import("value.zig");
12	
13	const SchemaNode = schema_mod.SchemaNode;
14	const Value = value_mod.Value;
15	
16	const max_nesting_depth: u32 = 64;
17	
18	/// Represents a single leaf column's flattened data
19	pub const FlatColumn = struct {
20	    values: std.ArrayList(Value),
21	    def_levels: std.ArrayList(u32),
22	    rep_levels: std.ArrayList(u32),
23	
24	    pub fn init() FlatColumn {
25	        return .{
26	            .values = .empty,
27	            .def_levels = .empty,
28	            .rep_levels = .empty,
29	        };
30	    }
31	
32	    pub fn deinit(self: *FlatColumn, allocator: std.mem.Allocator) void {
33	        self.values.deinit(allocator);
34	        self.def_levels.deinit(allocator);
35	        self.rep_levels.deinit(allocator);
36	    }
37	};
38	
39	/// Collection of flattened columns for a schema
40	pub const FlatColumns = struct {
41	    columns: std.ArrayList(FlatColumn),
42	    allocator: std.mem.Allocator,
43	
44	    pub fn init(allocator: std.mem.Allocator) FlatColumns {
45	        return .{
46	            .columns = .empty,
47	            .allocator = allocator,
48	        };
49	    }
50	
51	    pub fn deinit(self: *FlatColumns) void {
52	        for (self.columns.items) |*col| {
53	            col.deinit(self.allocator);
54	        }
55	        self.columns.deinit(self.allocator);
56	    }
57	
58	    pub fn addColumn(self: *FlatColumns) !*FlatColumn {
59	        try self.columns.append(self.allocator, FlatColumn.init());
60	        return &self.columns.items[self.columns.items.len - 1];
61	    }
62	};
63	
64	/// Context for tracking levels during flattening
65	const FlattenContext = struct {
66	    allocator: std.mem.Allocator,
67	    columns: *FlatColumns,
68	    current_def: u32,
69	    current_rep: u32,
70	    rep_depth: u32, // tracks which repetition level we're at
71	    column_index: usize,
72	};
73	
74	/// Flatten a nested Value according to its schema into flat columns with levels.
75	///
76	/// This is the inverse of `assembleValue` - it takes a nested structure and
77	/// produces flat arrays suitable for Parquet column encoding.
78	pub fn flattenValue(
79	    allocator: std.mem.Allocator,
80	    node: *const SchemaNode,
81	    value: Value,
82	) !FlatColumns {
83	    var columns = FlatColumns.init(allocator);
84	    errdefer columns.deinit();
85	
86	    // Pre-allocate columns for all leaves
87	    const num_leaves = node.countLeafColumns();
88	    for (0..num_leaves) |_| {
89	        _ = try columns.addColumn();
90	    }
91	
92	    var ctx = FlattenContext{
93	        .allocator = allocator,
94	        .columns = &columns,
95	        .current_def = 0,
96	        .current_rep = 0,
97	        .rep_depth = 0,
98	        .column_index = 0,
99	    };
100	
101	    try flattenRecursive(node, value, &ctx, false, 0);
102	
103	    return columns;
104	}
105	
106	fn flattenRecursive(
107	    node: *const SchemaNode,
108	    value: Value,
109	    ctx: *FlattenContext,
110	    is_repeated: bool,
111	    depth: u32,
112	) !void {
113	    if (depth > max_nesting_depth) return error.NestingTooDeep;
114	    switch (node.*) {
115	        .optional => |child| {
116	            if (value.isNull()) {
117	                // Write null marker to all leaf columns under this optional
118	                try writeNullToLeaves(child, ctx);
119	            } else {
120	                ctx.current_def += 1;
121	                try flattenRecursive(child, value, ctx, is_repeated, depth + 1);
122	                ctx.current_def -= 1;
123	            }
124	        },
125	        .list => |element| {
126	            // Parquet list encoding with definition and repetition levels:
127	            // Definition levels:
128	            //   def=0: list is null
129	            //   def=1: list exists but is empty
130	            //   def>=2: element exists (higher values for nested optional fields)
131	            // Repetition levels:
132	            //   rep=0: first element of a new record (new row)
133	            //   rep=1: subsequent element in the same list (repeated at list level)
134	            //   rep=2+: for nested lists, repeating at inner level
135	            const items = value.asList();
136	            if (items == null or value.isNull()) {
137	                // Null list: def=0, rep unchanged (uses current_rep from context)
138	                try writeNullToLeaves(element, ctx);
139	            } else if (items.?.len == 0) {
140	                // Empty list: def stays at current level (repeated group has no instances)
141	                try writeNullToLeaves(element, ctx);
142	            } else {
143	                ctx.current_def += 1;
144	                ctx.rep_depth += 1;
145	                for (items.?, 0..) |item, i| {
146	                    if (i > 0) {
147	                        // Subsequent elements: rep=rep_depth (indicates repetition at this list level)
148	                        ctx.current_rep = ctx.rep_depth;
149	                    }
150	                    try flattenRecursive(element, item, ctx, true, depth + 1);
151	                }
152	                ctx.rep_depth -= 1;
153	                ctx.current_def -= 1;
154	                if (!is_repeated) {
155	                    // Reset rep to 0 after processing list (ready for next top-level record)
156	                    ctx.current_rep = 0;
157	                }
158	            }
159	        },
160	        .map => |m| {
161	            // Map levels: key_value repeated group adds +1 def, +1 rep.
162	            // Parquet schema always marks map values as OPTIONAL, so add +1 def for value
163	            // unless the node already has an .optional wrapper.
164	            const entries = value.asMap();
165	            const key_leaves = m.key.countLeafColumns();
166	            const value_extra_def: u32 = if (m.value.* == .optional) 0 else 1;
167	
168	            if (entries == null or value.isNull()) {
169	                try writeNullToLeaves(m.key, ctx);
170	                ctx.column_index += key_leaves;
171	                try writeNullToLeaves(m.value, ctx);
172	                ctx.column_index -= key_leaves;
173	            } else if (entries.?.len == 0) {
174	                try writeNullToLeaves(m.key, ctx);
175	                ctx.column_index += key_leaves;
176	                try writeNullToLeaves(m.value, ctx);
177	                ctx.column_index -= key_leaves;
178	            } else {
179	                ctx.current_def += 1;
180	                ctx.rep_depth += 1;
181	                for (entries.?, 0..) |entry, i| {
182	                    if (i > 0) {
183	                        ctx.current_rep = ctx.rep_depth;
184	                    }
185	                    try flattenRecursive(m.key, entry.key, ctx, true, depth + 1);
186	                    ctx.column_index += key_leaves;
187	                    ctx.current_def += value_extra_def;
188	                    try flattenRecursive(m.value, entry.value, ctx, true, depth + 1);
189	                    ctx.current_def -= value_extra_def;
190	                    ctx.column_index -= key_leaves;
191	                }
192	                ctx.rep_depth -= 1;
193	                ctx.current_def -= 1;
194	                if (!is_repeated) {
195	                    ctx.current_rep = 0;
196	                }
197	            }
198	        },
199	        .struct_ => |s| {
200	            const fields = value.asStruct();
201	            if (fields == null or value.isNull()) {
202	                // Null struct - write nulls to all field columns
203	                for (s.fields) |f| {
204	                    try writeNullToLeaves(f.node, ctx);
205	                    ctx.column_index += f.node.countLeafColumns();
206	                }
207	                // Reset column index
208	                for (s.fields) |f| {
209	                    ctx.column_index -= f.node.countLeafColumns();
210	                }
211	            } else {
212	                // Match fields by name
213	                for (s.fields) |schema_field| {
214	                    var found = false;
215	                    for (fields.?) |value_field| {
216	                        if (std.mem.eql(u8, schema_field.name, value_field.name)) {
217	                            try flattenRecursive(schema_field.node, value_field.value, ctx, is_repeated, depth + 1);
218	                            found = true;
219	                            break;
220	                        }
221	                    }
222	                    if (!found) {
223	                        // Field not present, write null
224	                        try writeNullToLeaves(schema_field.node, ctx);
225	                    }
226	                    ctx.column_index += schema_field.node.countLeafColumns();
227	                }
228	                // Reset column index
229	                for (s.fields) |f| {
230	                    ctx.column_index -= f.node.countLeafColumns();
231	                }
232	            }
233	        },
234	        // Primitive types - write to column
235	        .boolean, .int32, .int64, .float, .double, .byte_array, .fixed_len_byte_array => {
236	            const col = &ctx.columns.columns.items[ctx.column_index];
237	            try col.values.append(ctx.allocator, value);
238	            try col.def_levels.append(ctx.allocator, ctx.current_def);
239	            try col.rep_levels.append(ctx.allocator, ctx.current_rep);
240	        },
241	    }
242	}
243	
244	fn writeNullToLeaves(node: *const SchemaNode, ctx: *FlattenContext) !void {
245	    switch (node.*) {
246	        .optional => |child| try writeNullToLeaves(child, ctx),
247	        .list => |element| try writeNullToLeaves(element, ctx),
248	        .map => |m| {
249	            try writeNullToLeaves(m.key, ctx);
250	            ctx.column_index += m.key.countLeafColumns();
251	            try writeNullToLeaves(m.value, ctx);
252	            ctx.column_index -= m.key.countLeafColumns();
253	        },
254	        .struct_ => |s| {
255	            for (s.fields) |f| {
256	                try writeNullToLeaves(f.node, ctx);
257	                ctx.column_index += f.node.countLeafColumns();
258	            }
259	            for (s.fields) |f| {
260	                ctx.column_index -= f.node.countLeafColumns();
261	            }
262	        },
263	        .boolean, .int32, .int64, .float, .double, .byte_array, .fixed_len_byte_array => {
264	            const col = &ctx.columns.columns.items[ctx.column_index];
265	            try col.values.append(ctx.allocator, .{ .null_val = {} });
266	            try col.def_levels.append(ctx.allocator, ctx.current_def);
267	            try col.rep_levels.append(ctx.allocator, ctx.current_rep);
268	        },
269	    }
270	}
271	
272	/// Context for tracking position during assembly
273	const AssembleContext = struct {
274	    allocator: std.mem.Allocator,
275	    columns: []const FlatColumnSlice,
276	    column_index: usize,
277	    positions: []usize, // current position in each column
278	};
279	
280	/// A view into a flat column's data
281	pub const FlatColumnSlice = struct {
282	    values: []const Value,
283	    def_levels: []const u32,
284	    rep_levels: []const u32,
285	};
286	
287	/// Assemble a nested Value from flat columns according to schema.
288	///
289	/// This is the inverse of `flattenValue` - it takes flat column data with
290	/// definition and repetition levels and reconstructs the nested structure.
291	fn assembleValue(
292	    allocator: std.mem.Allocator,
293	    node: *const SchemaNode,
294	    columns: []const FlatColumnSlice,
295	) !Value {
296	    const num_leaves = node.countLeafColumns();
297	    if (columns.len < num_leaves) {
298	        return error.NotEnoughColumns;
299	    }
300	
301	    const positions = try allocator.alloc(usize, columns.len);
302	    defer allocator.free(positions);
303	    @memset(positions, 0);
304	
305	    var ctx = AssembleContext{
306	        .allocator = allocator,
307	        .columns = columns,
308	        .column_index = 0,
309	        .positions = positions,
310	    };
311	
312	    return try assembleRecursive(node, &ctx, 0, 0, 0);
313	}
314	
315	/// Assemble multiple rows of nested Values from flat columns.
316	///
317	/// Like `assembleValue` but processes `num_rows` consecutive rows, keeping
318	/// position state across rows so each row picks up where the previous left off.
319	pub fn assembleValues(
320	    allocator: std.mem.Allocator,
321	    node: *const SchemaNode,
322	    columns: []const FlatColumnSlice,
323	    num_rows: usize,
324	) ![]Value {
325	    const num_leaves = node.countLeafColumns();
326	    if (columns.len < num_leaves) {
327	        return error.NotEnoughColumns;
328	    }
329	
330	    const positions = try allocator.alloc(usize, columns.len);
331	    defer allocator.free(positions);
332	    @memset(positions, 0);
333	
334	    var ctx = AssembleContext{
335	        .allocator = allocator,
336	        .columns = columns,
337	        .column_index = 0,
338	        .positions = positions,
339	    };
340	
341	    const result = try allocator.alloc(Value, num_rows);
342	    var initialized: usize = 0;
343	    errdefer {
344	        for (result[0..initialized]) |v| v.deinit(allocator);
345	        allocator.free(result);
346	    }
347	
348	    for (0..num_rows) |i| {
349	        ctx.column_index = 0;
350	        result[i] = try assembleRecursive(node, &ctx, 0, 0, 0);
351	        initialized += 1;
352	    }
353	    return result;
354	}
355	
356	fn assembleRecursive(
357	    node: *const SchemaNode,
358	    ctx: *AssembleContext,
359	    def_threshold: u32,
360	    rep_threshold: u32,
361	    depth: u32,
362	) !Value {
363	    if (depth > max_nesting_depth) return error.NestingTooDeep;
364	    switch (node.*) {
365	        .optional => |child| {
366	            // Check if we have data
367	            const col = ctx.columns[ctx.column_index];
368	            const pos = ctx.positions[ctx.column_index];
369	            if (pos >= col.def_levels.len) {
370	                return .{ .null_val = {} };
371	            }
372	
373	            const def = col.def_levels[pos];
374	            if (def <= def_threshold) {
375	                // Null at this level - consume the null
376	                consumeNullFromLeaves(child, ctx);
377	                return .{ .null_val = {} };
378	            }
379	
380	            return try assembleRecursive(child, ctx, def_threshold + 1, rep_threshold, depth + 1);
381	        },
382	        .list => |element| {
383	            const col = ctx.columns[ctx.column_index];
384	            const pos = ctx.positions[ctx.column_index];
385	            if (pos >= col.def_levels.len) {
386	                return .{ .null_val = {} };
387	            }
388	
389	            const def = col.def_levels[pos];
390	            if (def < def_threshold) {
391	                // Null list (for required lists this never triggers; for optional
392	                // lists the .optional wrapper handles null before reaching here)
393	                consumeNullFromLeaves(element, ctx);
394	                return .{ .null_val = {} };
395	            }
396	
397	            // Assemble list elements
398	            var items: std.ArrayList(Value) = .empty;
399	            errdefer {
400	                for (items.items) |item| item.deinit(ctx.allocator);
401	                items.deinit(ctx.allocator);
402	            }
403	
404	            var first = true;
405	            while (true) {
406	                const current_pos = ctx.positions[ctx.column_index];
407	                if (current_pos >= col.def_levels.len) break;
408	
409	                const current_rep = col.rep_levels[current_pos];
410	                if (!first and current_rep <= rep_threshold) break;
411	
412	                const current_def = col.def_levels[current_pos];
413	                if (current_def <= def_threshold) {
414	                    // Empty list marker
415	                    consumeNullFromLeaves(element, ctx);
416	                    break;
417	                }
418	
419	                const item = try assembleRecursive(element, ctx, def_threshold + 1, rep_threshold + 1, depth + 1);
420	                try items.append(ctx.allocator, item);
421	                first = false;
422	            }
423	
424	            const owned = try items.toOwnedSlice(ctx.allocator);
425	            return .{ .list_val = owned };
426	        },
427	        .map => |m| {
428	            const col = ctx.columns[ctx.column_index];
429	            const pos = ctx.positions[ctx.column_index];
430	            if (pos >= col.def_levels.len) {
431	                return .{ .null_val = {} };
432	            }
433	
434	            const def = col.def_levels[pos];
435	            if (def < def_threshold) {
436	                // Null map (for required maps, this never triggers; for optional
437	                // maps the .optional wrapper handles null before reaching here)
438	                consumeNullFromLeaves(m.key, ctx);
439	                ctx.column_index += m.key.countLeafColumns();
440	                consumeNullFromLeaves(m.value, ctx);
441	                ctx.column_index -= m.key.countLeafColumns();
442	                return .{ .null_val = {} };
443	            }
444	
445	            var entries: std.ArrayList(Value.MapEntryValue) = .empty;
446	            errdefer {
447	                for (entries.items) |entry| {
448	                    entry.key.deinit(ctx.allocator);
449	                    entry.value.deinit(ctx.allocator);
450	                }
451	                entries.deinit(ctx.allocator);
452	            }
453	
454	            const key_leaves = m.key.countLeafColumns();
455	            var first = true;
456	            while (true) {
457	                const current_pos = ctx.positions[ctx.column_index];
458	                if (current_pos >= col.def_levels.len) break;
459	
460	                const current_rep = col.rep_levels[current_pos];
461	                if (!first and current_rep <= rep_threshold) break;
462	
463	                const current_def = col.def_levels[current_pos];
464	                if (current_def <= def_threshold) {
465	                    // Empty map marker or end of entries
466	                    consumeNullFromLeaves(m.key, ctx);
467	                    ctx.column_index += key_leaves;
468	                    consumeNullFromLeaves(m.value, ctx);
469	                    ctx.column_index -= key_leaves;
470	                    break;
471	                }
472	
473	                const key = try assembleRecursive(m.key, ctx, def_threshold + 1, rep_threshold + 1, depth + 1);
474	                errdefer key.deinit(ctx.allocator);
475	                ctx.column_index += key_leaves;
476	                const val = try assembleRecursive(m.value, ctx, def_threshold + 1, rep_threshold + 1, depth + 1);
477	                errdefer val.deinit(ctx.allocator);
478	                ctx.column_index -= key_leaves;
479	
480	                try entries.append(ctx.allocator, .{ .key = key, .value = val });
481	                first = false;
482	            }
483	
484	            const owned = try entries.toOwnedSlice(ctx.allocator);
485	            return .{ .map_val = owned };
486	        },
487	        .struct_ => |s| {
488	            var fields: std.ArrayList(Value.FieldValue) = .empty;
489	            errdefer {
490	                for (fields.items) |f| {
491	                    ctx.allocator.free(f.name);
492	                    f.value.deinit(ctx.allocator);
493	                }
494	                fields.deinit(ctx.allocator);
495	            }
496	
497	            for (s.fields) |schema_field| {
498	                const field_value = try assembleRecursive(schema_field.node, ctx, def_threshold, rep_threshold, depth + 1);
499	                const name_copy = try ctx.allocator.dupe(u8, schema_field.name);
500	                try fields.append(ctx.allocator, .{ .name = name_copy, .value = field_value });
501	                ctx.column_index += schema_field.node.countLeafColumns();
502	            }
503	            // Reset column index
504	            for (s.fields) |f| {
505	                ctx.column_index -= f.node.countLeafColumns();
506	            }
507	
508	            const owned = try fields.toOwnedSlice(ctx.allocator);
509	            return .{ .struct_val = owned };
510	        },
511	        // Primitives - read from column (clone heap-allocated data to avoid double-free)
512	        .boolean, .int32, .int64, .float, .double, .byte_array, .fixed_len_byte_array => {
513	            const col = ctx.columns[ctx.column_index];
514	            const pos = ctx.positions[ctx.column_index];
515	            if (pos >= col.values.len) {
516	                return .{ .null_val = {} };
517	            }
518	            ctx.positions[ctx.column_index] += 1;
519	            const v = col.values[pos];
520	            return switch (v) {
521	                .bytes_val => |b| .{ .bytes_val = try value_mod.dupeBytes(ctx.allocator, b) },
522	                .fixed_bytes_val => |b| .{ .fixed_bytes_val = try value_mod.dupeBytes(ctx.allocator, b) },
523	                else => v,
524	            };
525	        },
526	    }
527	}
528	
529	fn consumeNullFromLeaves(node: *const SchemaNode, ctx: *AssembleContext) void {
530	    switch (node.*) {
531	        .optional => |child| consumeNullFromLeaves(child, ctx),
532	        .list => |element| consumeNullFromLeaves(element, ctx),
533	        .map => |m| {
534	            consumeNullFromLeaves(m.key, ctx);
535	            ctx.column_index += m.key.countLeafColumns();
536	            consumeNullFromLeaves(m.value, ctx);
537	            ctx.column_index -= m.key.countLeafColumns();
538	        },
539	        .struct_ => |s| {
540	            for (s.fields) |f| {
541	                consumeNullFromLeaves(f.node, ctx);
542	                ctx.column_index += f.node.countLeafColumns();
543	            }
544	            for (s.fields) |f| {
545	                ctx.column_index -= f.node.countLeafColumns();
546	            }
547	        },
548	        .boolean, .int32, .int64, .float, .double, .byte_array, .fixed_len_byte_array => {
549	            ctx.positions[ctx.column_index] += 1;
550	        },
551	    }
552	}
553	
554	pub const NestedError = error{
555	    NotEnoughColumns,
556	    OutOfMemory,
557	};
558	
559	// =============================================================================
560	// Tests
561	// =============================================================================
562	
563	test "flatten and assemble primitive" {
564	    const allocator = std.testing.allocator;
565	
566	    const schema = SchemaNode{ .int32 = .{} };
567	    const value = Value{ .int32_val = 42 };
568	
569	    var columns = try flattenValue(allocator, &schema, value);
570	    defer columns.deinit();
571	
572	    try std.testing.expectEqual(@as(usize, 1), columns.columns.items.len);
573	    try std.testing.expectEqual(@as(usize, 1), columns.columns.items[0].values.items.len);
574	    try std.testing.expectEqual(@as(i32, 42), columns.columns.items[0].values.items[0].asInt32().?);
575	
576	    // Assemble back
577	    const slices = [_]FlatColumnSlice{
578	        .{
579	            .values = columns.columns.items[0].values.items,
580	            .def_levels = columns.columns.items[0].def_levels.items,
581	            .rep_levels = columns.columns.items[0].rep_levels.items,
582	        },
583	    };
584	    const assembled = try assembleValue(allocator, &schema, &slices);
585	    try std.testing.expectEqual(@as(i32, 42), assembled.asInt32().?);
586	}
587	
588	test "flatten and assemble simple list" {
589	    const allocator = std.testing.allocator;
590	
591	    const element = SchemaNode{ .int32 = .{} };
592	    const schema = SchemaNode{ .list = &element };
593	
594	    const items = [_]Value{
595	        .{ .int32_val = 1 },
596	        .{ .int32_val = 2 },
597	        .{ .int32_val = 3 },
598	    };
599	    const value = Value{ .list_val = &items };
600	
601	    var columns = try flattenValue(allocator, &schema, value);
602	    defer columns.deinit();
603	
604	    try std.testing.expectEqual(@as(usize, 1), columns.columns.items.len);
605	    try std.testing.expectEqual(@as(usize, 3), columns.columns.items[0].values.items.len);
606	
607	    // Check levels
608	    const col = &columns.columns.items[0];
609	    try std.testing.expectEqual(@as(u32, 1), col.def_levels.items[0]);
610	    try std.testing.expectEqual(@as(u32, 1), col.def_levels.items[1]);
611	    try std.testing.expectEqual(@as(u32, 0), col.rep_levels.items[0]); // first item
612	    try std.testing.expectEqual(@as(u32, 1), col.rep_levels.items[1]); // continuation
613	}
614	
615	test "flatten and assemble struct" {
616	    const allocator = std.testing.allocator;
617	
618	    const id_node = SchemaNode{ .int64 = .{} };
619	    const name_node = SchemaNode{ .byte_array = .{} };
620	    const schema = SchemaNode{ .struct_ = .{
621	        .fields = &[_]SchemaNode.Field{
622	            .{ .name = "id", .node = &id_node },
623	            .{ .name = "name", .node = &name_node },
624	        },
625	    } };
626	
627	    const fields = [_]Value.FieldValue{
628	        .{ .name = "id", .value = .{ .int64_val = 123 } },
629	        .{ .name = "name", .value = .{ .bytes_val = "test" } },
630	    };
631	    const value = Value{ .struct_val = &fields };
632	
633	    var columns = try flattenValue(allocator, &schema, value);
634	    defer columns.deinit();
635	
636	    try std.testing.expectEqual(@as(usize, 2), columns.columns.items.len);
637	    try std.testing.expectEqual(@as(i64, 123), columns.columns.items[0].values.items[0].asInt64().?);
638	    try std.testing.expectEqualStrings("test", columns.columns.items[1].values.items[0].asBytes().?);
639	
640	    // Assemble back
641	    const slices = [_]FlatColumnSlice{
642	        .{
643	            .values = columns.columns.items[0].values.items,
644	            .def_levels = columns.columns.items[0].def_levels.items,
645	            .rep_levels = columns.columns.items[0].rep_levels.items,
646	        },
647	        .{
648	            .values = columns.columns.items[1].values.items,
649	            .def_levels = columns.columns.items[1].def_levels.items,
650	            .rep_levels = columns.columns.items[1].rep_levels.items,
651	        },
652	    };
653	    var assembled = try assembleValue(allocator, &schema, &slices);
654	    defer assembled.deinit(allocator);
655	
656	    try std.testing.expectEqual(@as(i64, 123), assembled.getField("id").?.asInt64().?);
657	    try std.testing.expectEqualStrings("test", assembled.getField("name").?.asBytes().?);
658	}
659	
660	test "assembleValues multi-row round trip" {
661	    const allocator = std.testing.allocator;
662	
663	    const schema = SchemaNode{ .int32 = .{} };
664	
665	    const values = [_]Value{ .{ .int32_val = 10 }, .{ .int32_val = 20 }, .{ .int32_val = 30 } };
666	    const def_levels = [_]u32{ 0, 0, 0 };
667	    const rep_levels = [_]u32{ 0, 0, 0 };
668	
669	    const slices = [_]FlatColumnSlice{
670	        .{
671	            .values = &values,
672	            .def_levels = &def_levels,
673	            .rep_levels = &rep_levels,
674	        },
675	    };
676	
677	    const result = try assembleValues(allocator, &schema, &slices, 3);
678	    defer {
679	        for (result) |v| v.deinit(allocator);
680	        allocator.free(result);
681	    }
682	
683	    try std.testing.expectEqual(@as(usize, 3), result.len);
684	    try std.testing.expectEqual(@as(i32, 10), result[0].asInt32().?);
685	    try std.testing.expectEqual(@as(i32, 20), result[1].asInt32().?);
686	    try std.testing.expectEqual(@as(i32, 30), result[2].asInt32().?);
687	}
688	
689	test "assembleValues not enough columns returns error" {
690	    const allocator = std.testing.allocator;
691	
692	    const id_node = SchemaNode{ .int64 = .{} };
693	    const name_node = SchemaNode{ .byte_array = .{} };
694	    const schema = SchemaNode{ .struct_ = .{
695	        .fields = &[_]SchemaNode.Field{
696	            .{ .name = "id", .node = &id_node },
697	            .{ .name = "name", .node = &name_node },
698	        },
699	    } };
700	
701	    const slices = [_]FlatColumnSlice{
702	        .{ .values = &.{}, .def_levels = &.{}, .rep_levels = &.{} },
703	    };
704	
705	    try std.testing.expectError(error.NotEnoughColumns, assembleValues(allocator, &schema, &slices, 1));
706	}
