    allocator.free(rg.columns);
    if (rg.sorting_columns) |sc| allocator.free(sc);
    rg.* = .{};
}

fn freeKeyValue(allocator: std.mem.Allocator, kv: *KeyValue) void {
    if (kv.key.len > 0) allocator.free(kv.key);
    if (kv.value) |v| allocator.free(v);
    kv.* = .{};
}

test "FileMetaData.parse frees partial state on OOM" {
    const allocator = std.testing.allocator;
    const io = std.testing.io;
    const file_buf = try std.Io.Dir.cwd().readFileAlloc(io, "../test-files-arrow/basic/basic_types_plain_uncompressed.parquet", allocator, @enumFromInt(1024 * 1024));
    defer allocator.free(file_buf);

    const footer_len: usize = std.mem.readInt(u32, file_buf[file_buf.len - 8 ..][0..4], .little);
    const footer = file_buf[file_buf.len - 8 - footer_len .. file_buf.len - 8];

    // Fail each allocation in turn. Every failing run must free what it built;
    // std.testing.allocator reports any leak from the backing allocator.
    var succeeded = false;
    var fail_index: usize = 0;
    while (fail_index < 256) : (fail_index += 1) {
        var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = fail_index });
        var reader = thrift.CompactReader.init(footer);
        var meta = FileMetaData.parse(failing.allocator(), &reader) catch |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
            continue;
        };
        meta.deinit(failing.allocator());
        succeeded = true;
        break;
    }
    try std.testing.expect(succeeded);
}

